/**
 * Points every issue that carries `sourceLabelId` at `targetLabelId`, then
 * deletes the source label. Issues that already carry the target keep it once.
 * Returns how many issues carried the source before the merge. Throws without
 * writing when the two ids are the same or either label is missing in `orgId`.
 */
export async function mergeLabelInto(
  orgId: OrgId,
  sourceLabelId: LabelId,
  targetLabelId: LabelId,
): Promise<number> {
  if (sourceLabelId === targetLabelId) {
    throw new Error("Cannot merge a label into itself");
  }

  const db = getDb();
  return db.transaction((tx) => {
    const source = tx
      .select({ id: labels.id })
      .from(labels)
      .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, sourceLabelId)))
      .get();
    const target = tx
      .select({ id: labels.id })
      .from(labels)
      .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, targetLabelId)))
      .get();
    if (!source || !target) {
      throw new Error(
        `Label ${source ? targetLabelId : sourceLabelId} not found`,
      );
    }

    const counted = tx
      .select({ value: count() })
      .from(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, sourceLabelId),
        ),
      )
      .get();
    const issuesRelabelled = counted?.value ?? 0;

    if (issuesRelabelled > 0) {
      const sourceIssueIds = tx
        .select({ issueId: issueLabels.issueId })
        .from(issueLabels)
        .where(
          and(
            orgPredicate(issueLabels.orgId, orgId),
            eq(issueLabels.labelId, sourceLabelId),
          ),
        )
        .all()
        .map((row) => row.issueId);

      const overlapping = tx
        .select({ issueId: issueLabels.issueId })
        .from(issueLabels)
        .where(
          and(
            orgPredicate(issueLabels.orgId, orgId),
            eq(issueLabels.labelId, targetLabelId),
            inArray(issueLabels.issueId, sourceIssueIds),
          ),
        )
        .all()
        .map((row) => row.issueId);

      if (overlapping.length > 0) {
        tx.delete(issueLabels)
          .where(
            and(
              orgPredicate(issueLabels.orgId, orgId),
              eq(issueLabels.labelId, sourceLabelId),
              inArray(issueLabels.issueId, overlapping),
            ),
          )
          .run();
      }

      tx.update(issueLabels)
        .set({ labelId: targetLabelId })
        .where(
          and(
            orgPredicate(issueLabels.orgId, orgId),
            eq(issueLabels.labelId, sourceLabelId),
          ),
        )
        .run();
    }

    tx.delete(labels)
      .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, sourceLabelId)))
      .run();

    return issuesRelabelled;
  });
}

