import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { mergeLabelsSchema } from "@/schemas/label";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as labelService from "@/server/services/label-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { LabelId, OrgId } from "@/types/common";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

const OTHER_ORG = "01HZZZBBBBBBBBBBBBBBBBBBBB" as OrgId;

describe("mergeLabels", () => {
  it("rejects identical ids in the schema", () => {
    const id = "01HZZZAAAAAAAAAAAAAAAAAAAA";
    const parsed = mergeLabelsSchema.safeParse({
      orgId: "01HZZZCCCCCCCCCCCCCCCCCCCCCC",
      sourceLabelId: id,
      targetLabelId: id,
    });
    expect(parsed.success).toBe(false);
  });

  it("folds source into target, including overlap and archived issues", async () => {
    const tenant = await createTenant("merge-happy", "growth");
    const defect = await labelRepo.insertLabel({
      orgId: tenant.org.id,
      name: "defect",
      color: "#ef4444",
      description: "old",
    });
    const bug = await labelRepo.insertLabel({
      orgId: tenant.org.id,
      name: "bug",
      color: "#22c55e",
      description: "keep",
    });
    const other = await labelRepo.insertLabel({
      orgId: tenant.org.id,
      name: "docs",
      color: "#94a3b8",
      description: null,
    });

    async function add(title: string, labelIds: LabelId[]) {
      const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
      return issueRepo.insertIssue(
        { ...issueInput(tenant.org.id, tenant.project.id, { title }), labelIds },
        tenant.userIds.owner,
        number,
      );
    }

    const onlySource = await add("only source", [defect.id]);
    const both = await add("both", [defect.id, bug.id]);
    const onlyTarget = await add("only target", [bug.id]);
    const untouched = await add("untouched", [other.id]);
    const archived = await add("archived source", [defect.id]);
    await issueRepo.archiveIssue(tenant.org.id, archived.id);
    const none = await add("none", []);

    const result = await labelService.mergeLabels(tenant.actors.admin, {
      orgId: tenant.org.id,
      sourceLabelId: defect.id,
      targetLabelId: bug.id,
    });

    expect(result.issuesRelabelled).toBe(3);
    expect(result.label).toMatchObject({
      id: bug.id,
      name: "bug",
      color: "#22c55e",
      description: "keep",
    });

    const labels = await labelRepo.listLabels(tenant.org.id);
    expect(labels.map((label) => label.id).sort()).toEqual([bug.id, other.id].sort());

    const ids = async (issueId: (typeof onlySource)["id"]) =>
      (await issueRepo.findIssueById(tenant.org.id, issueId))?.labelIds;

    expect(await ids(onlySource.id)).toEqual([bug.id]);
    expect(await ids(both.id)).toEqual([bug.id]);
    expect(await ids(onlyTarget.id)).toEqual([bug.id]);
    expect(await ids(untouched.id)).toEqual([other.id]);
    expect(await ids(archived.id)).toEqual([bug.id]);
    expect(await ids(none.id)).toEqual([]);

    const reread = await labelRepo.findLabelById(tenant.org.id, bug.id);
    expect(reread).toMatchObject({ name: "bug", color: "#22c55e", description: "keep" });
  });

  it("rejects cross-tenant, missing permission, missing labels, and self-merge", async () => {
    const tenant = await createTenant("merge-guards", "growth");
    const other = await createTenant("merge-other", "growth");
    const source = await labelRepo.insertLabel({
      orgId: tenant.org.id,
      name: "defect",
      color: "#ef4444",
      description: null,
    });
    const foreign = await labelRepo.insertLabel({
      orgId: other.org.id,
      name: "bug",
      color: "#22c55e",
      description: null,
    });

    await expect(
      labelService.mergeLabels(tenant.actors.admin, {
        orgId: OTHER_ORG,
        sourceLabelId: source.id,
        targetLabelId: foreign.id,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      labelService.mergeLabels(tenant.actors.member, {
        orgId: tenant.org.id,
        sourceLabelId: source.id,
        targetLabelId: foreign.id,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      labelService.mergeLabels(tenant.actors.admin, {
        orgId: tenant.org.id,
        sourceLabelId: source.id,
        targetLabelId: foreign.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      labelService.mergeLabels(tenant.actors.admin, {
        orgId: tenant.org.id,
        sourceLabelId: source.id,
        targetLabelId: source.id,
      }),
    ).rejects.toThrow();

    expect(await labelRepo.findLabelById(tenant.org.id, source.id)).not.toBeNull();
    expect(await labelRepo.findLabelById(other.org.id, foreign.id)).not.toBeNull();
    expect(await labelRepo.listLabels(tenant.org.id)).toHaveLength(1);
    expect(await labelRepo.listLabels(other.org.id)).toHaveLength(1);
  });
});

